insert into public.football_team_profiles (team_id, nickname, tags, intro) values
(100, '잘로로시', '{로마,스타디오 올림피코,1927년 창단}', $t$<p>AS 로마는 이탈리아의 수도 로마를 연고로 하며, 노랑과 빨강을 뜻하는 "잘로로시"라는 별명으로 불립니다. 세리에 A를 세 번 우승했고, 2022년에는 초대 UEFA 컨퍼런스리그 우승을 차지했습니다. 한 구단에서만 25년을 뛴 프란체스코 토티는 로마의 영원한 상징입니다. 같은 경기장을 쓰는 라치오와의 로마 더비는 도시 전체가 들썩이는 경기입니다.</p><p>토리코리 관전 포인트: 로마는 홈 관중의 열기에 크게 힘을 받는 팀입니다. 홈과 원정 경기당 승점 차이가 크다면 원정 성적 개선이 상위권 도약의 열쇠라는 뜻입니다.</p>$t$),
(108, '네라주리', '{밀라노,주세페 메아차,1908년 창단}', $t$<p>인테르나치오날레(인테르)는 외국인 선수 영입 문제로 AC 밀란에서 갈라져 나온 사람들이 세운 구단입니다. 이름처럼 "국제적인" 구단을 지향했으며, 세리에 A에서 한 번도 강등된 적이 없는 유일한 구단입니다. 2009-10 시즌 조제 무리뉴 감독과 함께 이탈리아 구단 최초로 트레블을 달성했고, 2024년 스쿠데토 20회를 채워 유니폼에 두 번째 별을 달았습니다.</p><p>토리코리 관전 포인트: 인테르는 스리백을 바탕으로 윙백이 공격에 깊이 가담하는 축구를 오래 유지해 왔습니다. 무실점 경기 수와 세트피스 득점이 많은 시즌에 성적이 좋았으니 수비 지표를 먼저 보세요.</p>$t$),
(110, '비앙코첼레스티', '{로마,스타디오 올림피코,1900년 창단}', $t$<p>SS 라치오는 로마에서 가장 오래된 축구 구단으로, 하늘색과 흰색 유니폼 때문에 "비앙코첼레스티"라고 불립니다. 홈 경기 전 독수리 "올림피아"가 경기장을 나는 전통이 유명합니다. 1973-74 시즌과 1999-2000 시즌 세리에 A 우승을 차지했고, 1999년에는 UEFA 컵위너스컵을 들어 올렸습니다.</p><p>토리코리 관전 포인트: 라치오는 로마 더비 결과가 시즌 분위기를 좌우할 만큼 라이벌전의 의미가 큰 팀입니다. 상위권 팀 상대 성적과 로마 더비 결과를 함께 보면 이번 시즌 라치오의 저력을 가늠할 수 있습니다.</p>$t$),
(104, '로소블루', '{칼리아리,사르데냐섬,1920년 창단}', $t$<p>칼리아리 칼초는 지중해의 섬 사르데냐를 대표하는 구단입니다. 1969-70 시즌 전설적인 공격수 지지 리바와 함께 섬 구단 최초로 세리에 A 우승을 차지하는 기적을 썼습니다. 섬 전체가 응원하는 구단이라 원정팀에게는 바다를 건너야 하는 부담스러운 원정지입니다.</p><p>토리코리 관전 포인트: 칼리아리는 1부와 2부를 오가며 잔류 싸움을 벌이는 경우가 많습니다. 원정 이동 거리가 긴 만큼 원정 경기당 승점이 특히 낮게 나오는지 살펴보면 좋습니다.</p>$t$),
(98, '로소네리', '{밀라노,주세페 메아차,1899년 창단}', $t$<p>AC 밀란은 잉글랜드인들이 세운 구단으로, 지금도 영어식 이름 "밀란"을 씁니다. 유러피언컵과 챔피언스리그를 일곱 번 우승해 레알 마드리드 다음으로 많은 유럽 정상 기록을 갖고 있습니다. 1980년대 말 아리고 사키 감독과 네덜란드 삼총사가 만든 압박 축구는 현대 축구에 큰 영향을 남겼습니다. 인테르와 산 시로를 함께 쓰며 치르는 밀라노 더비는 세계적인 라이벌전입니다.</p><p>토리코리 관전 포인트: 밀란은 빠른 측면 공격으로 골을 만드는 경기가 많습니다. 경기당 득점은 높은데 실점도 함께 높은 시즌이라면, 수비 안정이 우승 경쟁의 마지막 퍼즐입니다.</p>$t$),
(470, '카나리니', '{프로시노네,라치오주}', $t$<p>프로시노네 칼초는 로마 남동쪽의 작은 도시 프로시노네를 연고로 하는 구단입니다. 오랫동안 하부리그에 머물다 2015년 구단 역사상 처음으로 세리에 A 무대를 밟았고, 이후 1부와 2부를 오가며 경쟁하고 있습니다. 노란 유니폼 때문에 "카나리아"를 뜻하는 별명으로 불립니다.</p><p>토리코리 관전 포인트: 작은 구단이 세리에 A에서 살아남으려면 무엇보다 실점을 줄여야 합니다. 경기당 실점이 1.5골 아래로 유지되는지가 잔류 경쟁의 현실적인 기준입니다.</p>$t$),
(109, '비앙코네리', '{토리노,알리안츠 스타디움,1897년 창단}', $t$<p>유벤투스는 세리에 A 최다 우승 구단으로, 2011-12 시즌부터 9시즌 연속 스쿠데토라는 대기록을 세웠습니다. "노부인(베키아 시뇨라)"이라는 애칭으로 불리며, 이탈리아에서 가장 많은 팬을 가진 구단으로 꼽힙니다. 2006년 승부조작 스캔들(칼치오폴리)로 2부 리그로 강등되는 아픔도 겪었습니다. 같은 도시 토리노와의 더비는 "토리노 더비"라고 부릅니다.</p><p>토리코리 관전 포인트: 유벤투스는 전통적으로 적게 실점하고 이기는 팀입니다. 무실점 경기 비율이 40%를 넘는 시즌이 대체로 우승 경쟁을 한 시즌이었습니다.</p>$t$),
(7397, '라리아니', '{코모,스타디오 시닐리아,1907년 창단}', $t$<p>코모 1907은 알프스 자락의 아름다운 호수 도시 코모를 연고로 하는 구단입니다. 파산 뒤 하부리그로 떨어졌지만, 인도네시아 재벌 하르토노 형제가 인수한 뒤 과감한 투자로 빠르게 올라와 2024년 21년 만에 세리에 A로 복귀했습니다. 호숫가에 자리한 홈구장 시닐리아는 세계에서 가장 아름다운 경기장 가운데 하나로 꼽힙니다.</p><p>토리코리 관전 포인트: 코모는 기술 좋은 선수들을 모아 공을 소유하는 축구를 지향합니다. 점유율 축구를 하는 신흥 구단은 역습에 약한 경우가 많으니, 강팀을 상대로 실점이 얼마나 되는지 함께 보세요.</p>$t$),
(113, '파르테노페이', '{나폴리,디에고 아르만도 마라도나,1926년 창단}', $t$<p>SSC 나폴리는 이탈리아 남부를 대표하는 구단입니다. 디에고 마라도나와 함께 1987년과 1990년 세리에 A를 우승하며 북부 부자 구단들의 독주를 깼고, 홈구장 이름도 그를 기려 바뀌었습니다. 2022-23 시즌 33년 만에 우승할 때 김민재가 수비의 중심으로 활약해 한국 팬들에게도 특별한 구단이 됐고, 2024-25 시즌에도 다시 정상에 올랐습니다.</p><p>토리코리 관전 포인트: 나폴리의 홈 경기장은 이탈리아에서 가장 뜨거운 분위기를 자랑합니다. 홈 무패 기록과 홈 경기당 득점을 보면 우승 경쟁력이 바로 드러납니다.</p>$t$),
(471, '네로베르디', '{사수올로,마페이 스타디움,1920년 창단}', $t$<p>US 사수올로는 인구 4만 명 남짓한 작은 도시를 연고로 하는 구단으로, 건축자재 기업 마페이의 후원을 받아 성장했습니다. 2013년 처음 세리에 A에 올랐고, 기술 좋은 젊은 선수를 키워 빅클럽에 보내는 "선수 공장"으로 유명합니다. 초록과 검정 줄무늬 유니폼 때문에 "네로베르디"라고 불립니다.</p><p>토리코리 관전 포인트: 사수올로는 공격적인 축구로 득점도 실점도 많은 팀입니다. 2.5골 오버와 양팀 득점 비율이 리그 평균보다 높게 나오는 대표적인 팀이니, 경기 성향을 볼 때 참고하세요.</p>$t$),
(102, '라 데아', '{베르가모,게위스 스타디움,1907년 창단}', $t$<p>아탈란타는 밀라노 근교 도시 베르가모의 구단으로, "여신(라 데아)"이라는 애칭으로 불립니다. 뛰어난 유소년 육성으로 유명하며, 지안 피에로 가스페리니 감독 시절 과감한 대인 압박 축구로 챔피언스리그 단골 팀이 됐습니다. 2024년 유로파리그 결승에서 무패 행진 중이던 레버쿠젠을 3-0으로 꺾고 첫 유럽대항전 우승을 차지했습니다.</p><p>토리코리 관전 포인트: 아탈란타는 경기장 전체에서 일대일 대결을 거는 공격적인 팀입니다. 이런 스타일은 경기당 득점이 높고 후반에 골이 몰리는 경향이 있으니, 전·후반 득점 비율을 함께 보세요.</p>$t$),
(5890, '잘로로시', '{레체,스타디오 비아 델 마레,1908년 창단}', $t$<p>US 레체는 이탈리아 반도 "장화의 뒷굽"에 해당하는 살렌토 지방을 대표하는 구단입니다. 1부와 2부를 자주 오가지만, 남부 특유의 열정적인 홈 응원으로 원정팀을 괴롭히는 팀입니다. 적은 예산으로 해외의 숨은 유망주를 발굴해 키우는 능력이 뛰어나다는 평가를 받습니다.</p><p>토리코리 관전 포인트: 레체처럼 잔류를 목표로 하는 팀은 하위권 경쟁 팀과의 맞대결에서 승점을 챙기는 것이 중요합니다. 무승부가 많더라도 패배가 적다면 잔류 가능성이 높다는 신호입니다.</p>$t$),
(115, '체브레테', '{우디네,블루에너지 스타디움,1896년 창단}', $t$<p>우디네세 칼초는 이탈리아 북동부 프리울리 지방의 구단으로, 이탈리아에서 두 번째로 오래된 구단 가운데 하나입니다. 전 세계에 걸친 스카우트망으로 저평가된 선수를 찾아내 키운 뒤 비싸게 파는 운영으로 유명하며, 세리에 A에 꾸준히 머물러 온 중견 구단입니다. 흑백 줄무늬 유니폼 때문에 "작은 얼룩말"이라는 별명이 붙었습니다.</p><p>토리코리 관전 포인트: 우디네세는 체격이 좋은 선수들을 앞세운 몸싸움과 역습이 특징입니다. 점유율보다 경기당 실점과 세트피스 득점이 성적을 더 잘 설명하는 팀입니다.</p>$t$),
(586, '그라나타', '{토리노,스타디오 올림피코 그란데 토리노,1906년 창단}', $t$<p>토리노 FC는 1940년대 "그란데 토리노"라 불린 최강팀으로 세리에 A를 5연패했지만, 1949년 수페르가 언덕 비행기 사고로 선수단 대부분을 잃는 비극을 겪었습니다. 이 사고는 지금도 이탈리아 축구의 가장 큰 아픔으로 기억됩니다. 짙은 자주색(그라나타) 유니폼이 상징이며, 유벤투스와의 토리노 더비를 치릅니다.</p><p>토리코리 관전 포인트: 토리노는 중위권에서 단단한 수비로 버티는 시즌이 많습니다. 무승부 비율이 높은 편이라, 무승부를 승리로 바꾸는 힘이 순위를 끌어올리는 열쇠입니다.</p>$t$),
(112, '크로차티', '{파르마,스타디오 엔니오 타르디니,1913년 창단}', $t$<p>파르마는 1990년대 식품 기업 파르말라트의 후원으로 UEFA컵 두 번, 컵위너스컵 한 번을 우승하며 유럽 강호로 떠올랐습니다. 2015년 파산으로 4부 리그까지 떨어졌지만 3시즌 연속 승격이라는 기록을 세우며 세리에 A로 돌아왔습니다. 가슴의 십자가 문양 때문에 "크로차티(십자군)"라고 불립니다.</p><p>토리코리 관전 포인트: 파르마는 젊은 선수 중심으로 팀을 꾸리는 경우가 많아 경기 막판 집중력이 흔들리기도 합니다. 전반을 앞서고도 놓친 승점을 보면 경험 부족이 성적에 미치는 영향을 알 수 있습니다.</p>$t$),
(5911, '비앙코로시', '{몬차,U-파워 스타디움,1912년 창단}', $t$<p>AC 몬차는 F1 그랑프리 서킷으로 유명한 밀라노 근교 도시 몬차의 구단입니다. 2018년 실비오 베를루스코니와 아드리아노 갈리아니가 인수해 과감하게 투자했고, 2022년 구단 역사상 처음으로 세리에 A에 올랐습니다.</p><p>토리코리 관전 포인트: 몬차처럼 1부 경험이 짧은 구단은 원정 경기에서 승점을 쌓기가 어렵습니다. 원정 무득점 경기 수가 줄어드는지 보면 팀이 리그에 얼마나 적응했는지 알 수 있습니다.</p>$t$),
(99, '비올라', '{피렌체,아르테미오 프란키,1926년 창단}', $t$<p>ACF 피오렌티나는 르네상스의 도시 피렌체를 연고로 하며, 보라색 유니폼 때문에 "비올라"라고 불립니다. 세리에 A를 두 번 우승했고, 2023년과 2024년 두 시즌 연속 UEFA 컨퍼런스리그 결승에 올랐지만 모두 아쉽게 준우승에 그쳤습니다. 1930년대에 지어진 아르테미오 프란키는 역사적인 건축물로도 평가받습니다.</p><p>토리코리 관전 포인트: 피오렌티나는 유럽대항전을 병행하는 시즌이 많아 리그 일정이 빡빡합니다. 목요일 유럽 경기 뒤 주말 리그 경기 결과를 따로 모아 보면 로테이션의 영향이 드러납니다.</p>$t$),
(103, '로소블루', '{볼로냐,레나토 달라라,1909년 창단}', $t$<p>볼로냐 FC는 세리에 A를 일곱 번 우승한 전통 강호로, 마지막 우승은 1963-64 시즌입니다. 오랜 침체를 딛고 2024-25 시즌 60년 만에 챔피언스리그 무대에 섰고, 2025년에는 코파 이탈리아 결승에서 AC 밀란을 꺾고 51년 만에 주요 대회 우승을 차지했습니다.</p><p>토리코리 관전 포인트: 볼로냐의 최근 도약은 짧은 패스와 조직적인 압박을 바탕으로 이뤄졌습니다. 상위권 팀을 상대로 한 결과와 원정 경기당 승점을 함께 보면 이번 시즌 볼로냐가 어느 위치에 있는지 알 수 있습니다.</p>$t$),
(107, '그리포네', '{제노바,루이지 페라리스,1893년 창단}', $t$<p>제노아 CFC는 1893년 잉글랜드인들이 세운 이탈리아에서 가장 오래된 축구 구단입니다. 이탈리아 리그 초창기 아홉 번 우승한 명문이며, 같은 경기장을 쓰는 삼프도리아와의 "등대 더비(데르비 델라 란테르나)"는 이탈리아에서 가장 아름다운 응원전으로 꼽힙니다.</p><p>토리코리 관전 포인트: 제노아는 루이지 페라리스의 뜨거운 홈 응원에 힘입어 홈에서 강한 팀입니다. 홈 경기 무패 기록과 원정 경기 무득점 수를 비교해 보면 잔류 경쟁에서의 위치가 보입니다.</p>$t$),
(454, '아란초네로베르디', '{베네치아,스타디오 피에를루이지 펜초,1907년 창단}', $t$<p>베네치아 FC는 운하의 도시 베네치아를 연고로 하는 구단으로, 원정팀과 관중이 배를 타고 경기장에 가는 독특한 풍경으로 유명합니다. 주황·검정·초록이 어우러진 유니폼은 패션 브랜드와의 협업으로 축구 팬이 아닌 사람들에게도 인기가 높습니다. 1부와 2부를 오가며 경쟁하는 구단입니다.</p><p>토리코리 관전 포인트: 베네치아는 1부에 오를 때마다 공격적인 축구를 시도하지만 수비에서 고전했습니다. 경기당 실점과 무실점 경기 수가 잔류 경쟁의 핵심 지표입니다.</p>$t$)
